import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), k = nextInt();
        int[] cnt = new int[20001];  // values lie in -10000..10000
        for (int i = 0; i < n; i++) cnt[nextInt() + 10000]++;
        List<Integer> vals = new ArrayList<>();
        for (int v = 0; v <= 20000; v++)
            if (cnt[v] > 0) vals.add(v);
        vals.sort((a, b) -> cnt[a] != cnt[b] ? cnt[b] - cnt[a] : a - b);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < k; i++) {
            if (i > 0) sb.append(' ');
            sb.append(vals.get(i) - 10000);
        }
        System.out.println(sb);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"sort"
	"strconv"
	"strings"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, k := nextInt(), nextInt()
	c := map[int]int{}
	for i := 0; i < n; i++ {
		c[nextInt()]++
	}
	vals := make([]int, 0, len(c))
	for v := range c {
		vals = append(vals, v)
	}
	sort.Slice(vals, func(i, j int) bool {
		if c[vals[i]] != c[vals[j]] {
			return c[vals[i]] > c[vals[j]]
		}
		return vals[i] < vals[j]
	})
	out := make([]string, k)
	for i := range out {
		out[i] = strconv.Itoa(vals[i])
	}
	fmt.Println(strings.Join(out, " "))
}
